create table public.profiles(id uuid primary key references auth.users on delete cascade,name text not null check(length(name)<=80),username text unique,bio text default '' check(length(bio)<=300),is_admin boolean not null default false);
create table public.posts(id uuid primary key default gen_random_uuid(),author uuid not null references profiles(id) on delete cascade,body text not null check(length(body)<=1000),media text,media_type text check(media_type in ('image','video')),created_at timestamptz default now());
create table public.likes(post uuid references posts on delete cascade,actor uuid references profiles on delete cascade,primary key(post,actor));
create table public.follows(actor uuid references profiles on delete cascade,target uuid references profiles on delete cascade,primary key(actor,target),check(actor<>target));
create table public.comments(id uuid primary key default gen_random_uuid(),post uuid not null references posts on delete cascade,actor uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 1000),created_at timestamptz default now());
create table public.reports(id uuid primary key default gen_random_uuid(),post uuid not null references posts on delete cascade,actor uuid not null references profiles on delete cascade,reason text not null check(length(reason) between 1 and 1000));
create table public.messages(id uuid primary key default gen_random_uuid(),sender uuid not null references profiles on delete cascade,recipient uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 2000),created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),recipient uuid not null references profiles on delete cascade,body text not null,created_at timestamptz default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce((select is_admin from profiles where id=auth.uid()),false)$$;
do $$declare t text;begin foreach t in array array['profiles','posts','likes','follows','comments','reports','messages','notifications'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy profiles_read on profiles for select to authenticated using(true);
revoke update on profiles from authenticated;
grant update(name,bio) on profiles to authenticated;
create policy profiles_edit on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy posts_read on posts for select to authenticated using(true);
create policy posts_add on posts for insert to authenticated with check(author=auth.uid());
create policy posts_delete on posts for delete to authenticated using(author=auth.uid() or public.is_admin());
create policy likes_read on likes for select to authenticated using(true);
create policy likes_add on likes for insert to authenticated with check(actor=auth.uid());
create policy likes_delete on likes for delete to authenticated using(actor=auth.uid());
create policy follows_read on follows for select to authenticated using(true);
create policy follows_add on follows for insert to authenticated with check(actor=auth.uid());
create policy follows_update on follows for update to authenticated using(actor=auth.uid()) with check(actor=auth.uid());
create policy follows_delete on follows for delete to authenticated using(actor=auth.uid());
create policy comments_read on comments for select to authenticated using(true);
create policy comments_add on comments for insert to authenticated with check(actor=auth.uid());
create policy reports_add on reports for insert to authenticated with check(actor=auth.uid());
create policy reports_read on reports for select to authenticated using(public.is_admin());
create policy reports_delete on reports for delete to authenticated using(public.is_admin());
create policy messages_read on messages for select to authenticated using(sender=auth.uid() or recipient=auth.uid());
create policy messages_add on messages for insert to authenticated with check(sender=auth.uid());
create policy notifications_read on notifications for select to authenticated using(recipient=auth.uid());
create function public.notify_event() returns trigger language plpgsql security definer set search_path=public as $$declare dest uuid; msg text; src uuid;begin if tg_table_name='messages' then dest:=new.recipient;src:=new.sender;msg:='Нове повідомлення';elsif tg_table_name='follows' then dest:=new.target;src:=new.actor;msg:='Новий підписник';else select author into dest from posts where id=new.post;src:=new.actor;msg:=case when tg_table_name='likes' then 'Новий лайк' else 'Новий коментар' end;end if;if dest<>src then insert into notifications(recipient,body) values(dest,msg);end if;return new;end$$;
create trigger notify_like after insert on likes for each row execute function notify_event();
create trigger notify_comment after insert on comments for each row execute function notify_event();
create trigger notify_follow after insert on follows for each row execute function notify_event();
create trigger notify_message after insert on messages for each row execute function notify_event();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('media','media',true,10485760,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/quicktime','video/webm']);
create policy media_upload on storage.objects for insert to authenticated with check(bucket_id='media' and (storage.foldername(name))[1]=auth.uid()::text);
